## MethodChannel：请求/响应模式

MethodChannel 是最常用的 Channel 类型，适合「调用原生方法并等待结果」的场景。

### Dart 侧实现

```dart
class DeviceInfoService {
  static const _channel = MethodChannel('com.example.app/device_info');

  Future<String> getDeviceId() async {
    try {
      final deviceId = await _channel.invokeMethod<String>('getDeviceId');
      return deviceId ?? 'unknown';
    } on PlatformException catch (e) {
      // 原生侧抛出的异常
      throw DeviceInfoException('Failed to get device ID: ${e.message}');
    } on MissingPluginException {
      // Channel 未注册（通常是测试环境）
      return 'test-device-id';
    }
  }

  Future<Map<String, dynamic>> getSystemInfo() async {
    final result = await _channel.invokeMapMethod<String, dynamic>('getSystemInfo');
    return result ?? {};
  }
}
```

### Android 侧（Kotlin）

```kotlin
class DeviceInfoPlugin : FlutterPlugin, MethodCallHandler {
  private lateinit var channel: MethodChannel
  private lateinit var context: Context

  override fun onAttachedToEngine(binding: FlutterPlugin.FlutterPluginBinding) {
    channel = MethodChannel(binding.binaryMessenger, "com.example.app/device_info")
    channel.setMethodCallHandler(this)
    context = binding.applicationContext
  }

  override fun onMethodCall(call: MethodCall, result: Result) {
    when (call.method) {
      "getDeviceId" -> {
        val deviceId = Settings.Secure.getString(
          context.contentResolver,
          Settings.Secure.ANDROID_ID
        )
        result.success(deviceId)
      }
      "getSystemInfo" -> {
        result.success(mapOf(
          "os" to "Android",
          "version" to Build.VERSION.RELEASE,
          "model" to Build.MODEL
        ))
      }
      else -> result.notImplemented()
    }
  }

  override fun onDetachedFromEngine(binding: FlutterPlugin.FlutterPluginBinding) {
    channel.setMethodCallHandler(null)
  }
}
```

### iOS 侧（Swift）

```swift
public class DeviceInfoPlugin: NSObject, FlutterPlugin {
  public static func register(with registrar: FlutterPluginRegistrar) {
    let channel = FlutterMethodChannel(
      name: "com.example.app/device_info",
      binaryMessenger: registrar.messenger()
    )
    let instance = DeviceInfoPlugin()
    registrar.addMethodCallDelegate(instance, channel: channel)
  }

  public func handle(_ call: FlutterMethodCall, result: @escaping FlutterResult) {
    switch call.method {
    case "getDeviceId":
      result(UIDevice.current.identifierForVendor?.uuidString ?? "unknown")
    case "getSystemInfo":
      result([
        "os": "iOS",
        "version": UIDevice.current.systemVersion,
        "model": UIDevice.current.model
      ])
    default:
      result(FlutterMethodNotImplemented)
    }
  }
}
```

