## EventChannel：持续事件流

EventChannel 适合「订阅原生事件流」的场景，如传感器数据、位置更新。

```dart
class AccelerometerService {
  static const _channel = EventChannel('com.example.app/accelerometer');

  Stream<AccelerometerData> get dataStream {
    return _channel.receiveBroadcastStream().map((event) {
      final map = Map<String, double>.from(event as Map);
      return AccelerometerData(
        x: map['x'] ?? 0,
        y: map['y'] ?? 0,
        z: map['z'] ?? 0,
      );
    });
  }
}
```

Android Kotlin 侧：

```kotlin
class AccelerometerPlugin : FlutterPlugin, EventChannel.StreamHandler {
  private lateinit var eventChannel: EventChannel
  private var eventSink: EventChannel.EventSink? = null
  private lateinit var sensorManager: SensorManager

  override fun onListen(arguments: Any?, events: EventChannel.EventSink) {
    eventSink = events
    // 注册传感器监听
    val sensor = sensorManager.getDefaultSensor(Sensor.TYPE_ACCELEROMETER)
    sensorManager.registerListener(sensorListener, sensor,
      SensorManager.SENSOR_DELAY_NORMAL)
  }

  override fun onCancel(arguments: Any?) {
    sensorManager.unregisterListener(sensorListener)
    eventSink = null
  }

  private val sensorListener = object : SensorEventListener {
    override fun onSensorChanged(event: SensorEvent) {
      eventSink?.success(mapOf(
        "x" to event.values[0],
        "y" to event.values[1],
        "z" to event.values[2]
      ))
    }
    override fun onAccuracyChanged(sensor: Sensor, accuracy: Int) {}
  }
}
```

